class TransientStoreError(Exception):
    pass


class Checkout:
    def __init__(self, store, notifications):
        self.store = store
        self.notifications = notifications

    def pay(self, order_id):
        if self.store.is_paid(order_id):
            return
        for attempt in range(3):
            try:
                self.notifications.send(order_id)
                self.store.mark_paid(order_id)
                return
            except TransientStoreError:
                if attempt == 2:
                    raise


class MemoryStore:
    def __init__(self, failures=0):
        self.failures = failures
        self.paid = set()
        self.attempts = 0

    def is_paid(self, order_id):
        return order_id in self.paid

    def mark_paid(self, order_id):
        self.attempts += 1
        if self.failures:
            self.failures -= 1
            raise TransientStoreError('write temporarily unavailable')
        self.paid.add(order_id)


class MemoryNotifications:
    def __init__(self):
        self.sent = []

    def send(self, order_id):
        self.sent.append(order_id)

